begin;
select plan(62);
create temp table _r (k text primary key, r jsonb);
grant all on _r to anon;
create temp table _t as select (now() at time zone 'Asia/Kuala_Lumpur')::time as t;
grant select on _t to anon;
set local role anon;

insert into _r select 'p1', public.place_order('lapar-local-a-table-01', jsonb_build_array(format('{"itemId":"%s","qty":2,"optionIds":["%s"],"priceSen":1,"unitPriceSen":1,"lineTotalSen":1,"optionsPriceSen":0}', md5('item:a:kopi')::uuid, md5('option:a:kopi:panas')::uuid)::jsonb));
select is((select r #>> '{lines,0,unitPriceSen}' from _r where k = 'p1'), '200', 'price comes from the database even if the JSON carries price fields');
select is((select r #>> '{totalSen}' from _r where k = 'p1'), '400', 'total is qty x server price');
select is((select r #>> '{status}' from _r where k = 'p1'), 'pending_approval', 'A: first order needs approval');
insert into _r select 'p2', public.place_order('lapar-local-a-table-01', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s","%s"],"note":"  less ice  "}', md5('item:a:teh-tarik')::uuid, md5('option:a:teh-tarik:ais')::uuid, md5('option:a:teh-tarik:bungkus')::uuid)::jsonb));
select is((select r #>> '{lines,0,optionsPriceSen}' from _r where k = 'p2'), '50', 'option deltas add up (30 + 20)');
select is((select r #>> '{totalSen}' from _r where k = 'p2'), '270', 'line total includes options');
select is((select r #>> '{tabId}' from _r where k = 'p2'), (select r #>> '{tabId}' from _r where k = 'p1'), 'a table keeps one open tab');
reset role;
create temp table _n as select (select count(*) from public.order_items where note = 'less ice') as c; grant select on _n to anon;
set local role anon;
select is((select c from _n), 1::bigint, 'note is trimmed before saving');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:teh-tarik')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'required option group missing');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s","%s"]}', md5('item:a:roti-canai')::uuid, md5('option:a:roti-canai:dhal')::uuid, md5('option:a:roti-canai:kari')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'too many options in a group');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:a:kopi')::uuid, md5('option:a:teh-tarik:ais')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'option of another item');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:a:kopi')::uuid, md5('option:b:kopi:panas')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'option of another shops item');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s","%s"]}', md5('item:a:kopi')::uuid, md5('option:a:kopi:panas')::uuid, md5('option:a:kopi:panas')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'duplicate option ids');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:b:kopi')::uuid)::jsonb))$$, 'P0001', 'item_unavailable', 'other shops item: item_unavailable');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":0}', md5('item:a:mee-rebus')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'qty 0');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":100}', md5('item:a:mee-rebus')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'qty 100');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(jsonb_build_object('itemId', md5('item:a:mee-rebus')::uuid, 'qty', '2')))$$, 'P0001', 'invalid_input', 'qty as a string');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(jsonb_build_object('itemId', 'not-a-uuid', 'qty', 1)))$$, 'P0001', 'invalid_input', 'item id not a uuid');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(jsonb_build_object('qty', 1)))$$, 'P0001', 'invalid_input', 'item id missing');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1,"note":"xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"}', md5('item:a:mee-rebus')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'note of 141 characters');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb))$$, 'P0001', 'invalid_input', '31 lines');
select throws_ok($$select public.place_order('lapar-local-a-table-02', '[]'::jsonb)$$, 'P0001', 'invalid_input', '0 lines');
select throws_ok($$select public.place_order('lapar-local-a-table-02', '{}'::jsonb)$$, 'P0001', 'invalid_input', 'lines must be an array');
select throws_ok($$select public.place_order('lapar-local-a-table-02', null::jsonb)$$, 'P0001', 'invalid_input', 'null lines');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb), now())$$, 'P0001', 'invalid_input', 'pickup_at on a table');
select throws_ok($$select public.place_order('no-such-token-xxxxxxxxxxxxxxxx', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb))$$, 'P0001', 'not_found', 'unknown token');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb, format('{"itemId":"%s","qty":1}', md5('item:a:teh-tarik')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'a bad second line refuses the whole order');
reset role;
create temp table _n2 as select (select count(*) from public.orders o join public.tabs t on t.id = o.tab_id where t.table_id = md5('table:a:02')::uuid) as c, (select count(*) from public.tabs where table_id = md5('table:a:02')::uuid) as tabs; grant select on _n2 to anon;
set local role anon;
select is((select c + tabs from _n2), 0::bigint, 'failed orders leave no order or tab behind');
reset role;
update public.items set sold_out = true where id = md5('item:a:mee-rebus')::uuid;
update public.items set active = false where id = md5('item:a:mee-goreng-mamak')::uuid;
set local role anon;
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:mee-rebus')::uuid)::jsonb))$$, 'P0001', 'sold_out', 'sold out item');
select throws_ok($$select public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:a:mee-goreng-mamak')::uuid, md5('option:a:mee-goreng-mamak:biasa')::uuid)::jsonb))$$, 'P0001', 'item_unavailable', 'inactive item');
reset role;
update public.categories set available_from = ((select t from _t) + interval '2 hours')::time, available_to = ((select t from _t) + interval '3 hours')::time where id = md5('cat:a:noodles')::uuid;
set local role anon;
insert into _r select 'w1', public.place_order('lapar-local-a-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:a:char-kuey-teow')::uuid, md5('option:a:char-kuey-teow:biasa')::uuid)::jsonb));
select is((select r #>> '{totalSen}' from _r where k = 'w1'), '900', 'A: a stored category window is ignored without timed_menus');
select is((select count(*) from generate_series(1, 5) g where public.place_order('lapar-local-a-table-03', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:a:kopi-o')::uuid, md5('option:a:kopi-o:panas')::uuid)::jsonb)) is not null), 5::bigint, 'five orders in 5 minutes are accepted');
select throws_ok($$select public.place_order('lapar-local-a-table-03', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:a:kopi-o')::uuid, md5('option:a:kopi-o:panas')::uuid)::jsonb))$$, 'P0001', 'rate_limited', '6th order in 5 minutes');
select lives_ok($$select public.place_order('lapar-local-a-table-04', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:telur-mata')::uuid)::jsonb))$$, 'another table has its own limit');
reset role;
update public.shops set active = false where id = md5('shop:a')::uuid;
set local role anon;
select throws_ok($$select public.place_order('lapar-local-a-table-05', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:telur-mata')::uuid)::jsonb))$$, 'P0001', 'shop_inactive', 'inactive shop');
reset role;
update public.shops set active = true where id = md5('shop:a')::uuid;
set local role anon;
reset role;
update public.shops set approval_mode = 'every_order' where id = md5('shop:a')::uuid;
set local role anon;
insert into _r select 'e1', public.place_order('lapar-local-a-table-06', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:telur-mata')::uuid)::jsonb));
insert into _r select 'e2', public.place_order('lapar-local-a-table-06', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:telur-mata')::uuid)::jsonb));
select is((select r #>> '{status}' from _r where k = 'e1') || ',' || (select r #>> '{status}' from _r where k = 'e2'), 'pending_approval,pending_approval', 'every_order: all orders wait');
reset role;
update public.shops set approval_mode = 'none' where id = md5('shop:a')::uuid;
set local role anon;
insert into _r select 'n1', public.place_order('lapar-local-a-table-07', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:telur-mata')::uuid)::jsonb));
select is((select r #>> '{status}' from _r where k = 'n1'), 'approved', 'none: order approved at once');
reset role;
create temp table _n3 as select count(*) as c from public.order_items oi join public.orders o on o.id = oi.order_id where o.id = (select (r ->> 'orderId')::uuid from _r where k = 'n1') and oi.status = 'new' and o.approved_at is not null; grant select on _n3 to anon;
set local role anon;
select is((select c from _n3), 1::bigint, 'approved order: lines are new and approved_at is set');
reset role;
update public.shops set approval_mode = 'first_order' where id = md5('shop:a')::uuid;
set local role anon;
insert into _r select 'f1', public.place_order('lapar-local-a-table-08', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:telur-mata')::uuid)::jsonb));
select is((select r #>> '{status}' from _r where k = 'f1'), 'pending_approval', 'first_order: the first order waits');
reset role;
update public.orders set status = 'approved', approved_at = now() where id = (select (r ->> 'orderId')::uuid from _r where k = 'f1');
set local role anon;
insert into _r select 'f2', public.place_order('lapar-local-a-table-08', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:telur-mata')::uuid)::jsonb));
select is((select r #>> '{status}' from _r where k = 'f2'), 'approved', 'first_order: later orders auto-approve once one is approved');
insert into _r select 'f3', public.place_order('lapar-local-a-table-09', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:telur-mata')::uuid)::jsonb));
select is((select r #>> '{status}' from _r where k = 'f3'), 'pending_approval', 'first_order is per tab');
reset role;
update public.shops set approval_mode = 'every_order' where id = md5('shop:a')::uuid;
insert into public.shop_feature_overrides (shop_id, feature_key, enabled, note) values (md5('shop:a')::uuid, 'approvals', false, 'test');
set local role anon;
insert into _r select 'o1', public.place_order('lapar-local-a-table-10', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:a:telur-mata')::uuid)::jsonb));
select is((select r #>> '{status}' from _r where k = 'o1'), 'approved', 'approvals feature off: approved whatever the mode');
reset role;
update public.promos set start_time = '00:00', end_time = '23:59' where id = md5('promo:b:happy-hour')::uuid;
set local role anon;
insert into _r select 'b1', public.place_order('lapar-local-b-table-01', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:b:teh-tarik')::uuid, md5('option:b:teh-tarik:ais')::uuid)::jsonb));
select is((select r #>> '{lines,0,unitPriceSen}' from _r where k = 'b1') || ',' || (select r #>> '{lines,0,listPriceSen}' from _r where k = 'b1') || ',' || (select r #>> '{lines,0,lineTotalSen}' from _r where k = 'b1'), '176,220,206', 'B: promo covering now: 176 sen, list 220, options not discounted');
select is((select r #>> '{lines,0,promoId}' from _r where k = 'b1'), md5('promo:b:happy-hour')::uuid::text, 'B: promo id recorded');
reset role;
update public.promos set start_time = ((select t from _t) + interval '2 hours')::time, end_time = ((select t from _t) + interval '3 hours')::time where id = md5('promo:b:happy-hour')::uuid;
set local role anon;
insert into _r select 'b2', public.place_order('lapar-local-b-table-01', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:b:teh-tarik')::uuid, md5('option:b:teh-tarik:panas')::uuid)::jsonb));
select is((select r #>> '{lines,0,unitPriceSen}' from _r where k = 'b2'), '220', 'B: promo outside its window: list price');
reset role;
update public.categories set available_from = ((select t from _t) + interval '2 hours')::time, available_to = ((select t from _t) + interval '3 hours')::time where id = md5('cat:b:breakfast')::uuid;
set local role anon;
select throws_ok($$select public.place_order('lapar-local-b-table-01', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:b:kaya-toast')::uuid)::jsonb))$$, 'P0001', 'item_unavailable', 'B: category window excludes now');
reset role;
update public.categories set available_from = '00:00', available_to = '23:59' where id = md5('cat:b:breakfast')::uuid;
set local role anon;
insert into _r select 'b3', public.place_order('lapar-local-b-table-01', jsonb_build_array(format('{"itemId":"%s","qty":1,"suggestedFromItemId":"%s"}', md5('item:b:kaya-toast')::uuid, md5('item:b:nasi-lemak')::uuid)::jsonb));
reset role;
create temp table _sg as select count(*) as c from public.order_items where suggested_from_item_id = md5('item:b:nasi-lemak')::uuid; grant select on _sg to anon;
set local role anon;
select is((select c from _sg), 1::bigint, 'B: suggestedFromItemId stored');
select throws_ok($$select public.place_order('lapar-local-b-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1,"suggestedFromItemId":"%s"}', md5('item:b:kaya-toast')::uuid, md5('item:a:kopi')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'suggestedFromItemId of another shop');
insert into _r select 's1', public.place_order('lapar-local-b-table-03', jsonb_build_array(format('{"itemId":"%s","qty":2}', md5('item:b:set-a')::uuid)::jsonb));
select is((select r #>> '{totalSen}' from _r where k = 's1'), '1400', 'Set A x2: the set is priced once (700 x 2)');
select is((select jsonb_array_length(r -> 'lines') from _r where k = 's1'), 3, 'Set A: set line plus two component lines');
reset role;
create temp table _s as select oi.line_no, oi.kind, oi.qty, oi.unit_price_sen, oi.station_id from public.order_items oi where oi.order_id = (select (r ->> 'orderId')::uuid from _r where k = 's1'); grant select on _s to anon;
set local role anon;
select is((select array_agg(kind::text order by line_no) from _s), array['combo','component','component'], 'Set A: line kinds in order');
select is((select array_agg(qty::int order by line_no) from _s), array[2,2,2], 'Set A: component qty = set qty x component qty');
select is((select array_agg(unit_price_sen order by line_no) from _s), array[700,0,0], 'Set A: components carry no price');
select is((select array_agg(station_id order by line_no) from _s), array[md5('station:b:kitchen')::uuid, md5('station:b:kitchen')::uuid, md5('station:b:drinks')::uuid], 'B: Teh tarik routed to Drinks, the rest to Kitchen');
select throws_ok($$select public.place_order('lapar-local-b-table-03', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:b:set-a')::uuid, md5('option:b:teh-tarik:ais')::uuid)::jsonb))$$, 'P0001', 'invalid_input', 'a set takes no options');
reset role;
insert into public.shop_feature_overrides (shop_id, feature_key, enabled, note) values (md5('shop:b')::uuid, 'multi_station', false, 'test');
set local role anon;
insert into _r select 's2', public.place_order('lapar-local-b-table-04', jsonb_build_array(format('{"itemId":"%s","qty":1}', md5('item:b:set-a')::uuid)::jsonb));
reset role;
create temp table _s2 as select distinct oi.station_id from public.order_items oi where oi.order_id = (select (r ->> 'orderId')::uuid from _r where k = 's2'); grant select on _s2 to anon;
set local role anon;
select is((select array_agg(station_id) from _s2), array[md5('station:b:kitchen')::uuid], 'multi_station off: every line goes to the first station');
insert into _r select 'c1', public.place_order('lapar-local-b-counter-1', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:b:roti-canai')::uuid, md5('option:b:roti-canai:dhal')::uuid)::jsonb));
insert into _r select 'c2', public.place_order('lapar-local-b-counter-1', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:b:roti-canai')::uuid, md5('option:b:roti-canai:dhal')::uuid)::jsonb), now());
select is((select r #>> '{pickupNo}' from _r where k = 'c1') || ',' || (select r #>> '{pickupNo}' from _r where k = 'c2'), '1,2', 'counter orders get pickup numbers 1 and 2');
select isnt((select r #>> '{tabId}' from _r where k = 'c1'), (select r #>> '{tabId}' from _r where k = 'c2'), 'each counter order opens its own tab');
reset role;
create temp table _c as select (select pickup_at is not null from public.tabs where id = (select (r ->> 'tabId')::uuid from _r where k = 'c2')) as has_pickup; grant select on _c to anon;
set local role anon;
select is((select has_pickup from _c), true, 'counter tab keeps the requested pickup time');
select throws_ok($$select public.place_order('lapar-local-b-counter-1', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:b:roti-canai')::uuid, md5('option:b:roti-canai:dhal')::uuid)::jsonb), now() - interval '1 hour')$$, 'P0001', 'invalid_input', 'pickup time in the past');
select throws_ok($$select public.place_order('lapar-local-b-counter-1', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:b:roti-canai')::uuid, md5('option:b:roti-canai:dhal')::uuid)::jsonb), now() + interval '1 day')$$, 'P0001', 'invalid_input', 'pickup time on another day');
reset role;
insert into public.shop_feature_overrides (shop_id, feature_key, enabled, note) values (md5('shop:b')::uuid, 'takeaway', false, 'test');
set local role anon;
select throws_ok($$select public.place_order('lapar-local-b-counter-1', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:b:roti-canai')::uuid, md5('option:b:roti-canai:dhal')::uuid)::jsonb))$$, 'P0001', 'feature_not_enabled', 'counter without takeaway');
reset role;
insert into public.shop_feature_overrides (shop_id, feature_key, enabled, note) values (md5('shop:b')::uuid, 'modifiers', false, 'test');
set local role anon;
select throws_ok($$select public.place_order('lapar-local-b-table-02', jsonb_build_array(format('{"itemId":"%s","qty":1,"optionIds":["%s"]}', md5('item:b:kopi')::uuid, md5('option:b:kopi:panas')::uuid)::jsonb))$$, 'P0001', 'feature_not_enabled', 'options need the modifiers feature');

select * from finish();
rollback;
